import{_ as t,o as r,c as o,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Orchestrator Meeting 2022-02-22","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2022-02-22","date":"2022-02-22T00:00:00.000Z","updated":"2022-02-23T00:00:00.000Z","tags":["Ceph","Monitoring","Prometheus","Storage Optimization","High Availability"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Ceph_Orchestrator_Meeting_2022-02-22.md","filePath":"posts/2022/Ceph_Orchestrator_Meeting_2022-02-22.md","lastUpdated":1780459816000}'),p={name:"posts/2022/Ceph_Orchestrator_Meeting_2022-02-22.md"};function i(a,e,n,h,_,l){return r(),o("div",null,[...e[0]||(e[0]=[s("<p>本次Ceph Orchestrator会议主要讨论了以下议题：</p><ol><li><p><strong>主机缓存对象问题</strong>：当前主机缓存对象过大，影响了Monkey Store的性能。会议提出了增加Monkey Store大小限制、分割主机缓存对象、使用数据压缩等解决方案。</p></li><li><p><strong>配置和密钥环存储位置</strong>：讨论了将配置和密钥环从Etsy Stuff迁移到var/lib/fsid的可能性，以提高管理和推理的便利性。决定支持在两个位置同时存储的方案。</p></li><li><p><strong>Prometheus版本升级</strong>：讨论了升级Prometheus版本的需求，特别是为了支持外部Prometheus实例的功能。建议升级到2.28版本。</p></li><li><p><strong>支持外部Prometheus实例</strong>：讨论了如何支持用户使用外部的Prometheus实例来监控Ceph集群。决定在Ceph中创建一个端点供外部Prometheus实例获取配置信息。</p></li><li><p><strong>Prometheus高可用性（HA）配置</strong>：讨论了使用RBD图像存储Prometheus的配置和数据以实现高可用性。会议对此方案提出了多个问题，包括依赖集群本身的可用性、数据写入的复杂性以及存储需求等。</p></li></ol><p>会议决定事项包括：探索分割缓存对象和数据压缩的解决方案、支持在两个位置同时存储配置和密钥环、进一步研究和测试Prometheus版本升级的可行性、开发外部Prometheus实例的端点支持、讨论和评估Prometheus HA配置的可行性。</p><p>后续行动计划包括：实施主机缓存对象分割和数据压缩的方案、实现配置和密钥环在两个位置同时存储的功能、进行Prometheus版本升级的测试和验证、开发并测试外部Prometheus实例的端点支持、进一步讨论和评估Prometheus HA配置的可行性。</p>",4)])])}const g=t(p,[["render",i]]);export{u as __pageData,g as default};
